class BojlerTuvCard extends HTMLElement {
  setConfig(config) {
    this._cfg = { ...DEFAULTS, ...config, uid: 'bt' };
    this._ids = ENTITY_KEYS.map(k => this._cfg[k]).filter(Boolean);
    this._last = null;
    if (this._hass) this._render();
  }

  // Perf: HA calls this on every state change anywhere; redraw only when one of our entities changed.
  set hass(hass) {
    this._hass = hass;
    if (!this._cfg) return;
    const last = this._last;
    if (last && this._ids.every(id => hass.states[id] === last[id])) return;
    this._last = Object.fromEntries(this._ids.map(id => [id, hass.states[id]]));
    this._render();
  }

  _render() {
    if (!this.shadowRoot) {
      this.attachShadow({ mode: 'open' }).innerHTML = `
        <style>ha-card { padding: 16px; } .msg { color: var(--secondary-text-color); font-size: 14px; }</style>
        <ha-card><div id="c"></div></ha-card>`;
    }
    const el = this.shadowRoot.getElementById('c');
    if (!this._cfg.boiler || !this._cfg.valve) {
      el.innerHTML = '<div class="msg">Vyber entitu bojlera (teplota) a ventilu v editore karty.</div>';
      return;
    }
    el.innerHTML = renderCard(this._hass.states, this._cfg);
  }

  getCardSize() { return 6; }
  getGridOptions() { return { columns: 12, min_columns: 6 }; }

  static getConfigElement() { return document.createElement('bojler-tuv-card-editor'); }

  static getStubConfig(hass) {
    const ids = Object.keys(hass?.states || {});
    const temp = ids.filter(id => id.startsWith('sensor.') && hass.states[id].attributes.device_class === 'temperature');
    const pick = (list, re) => list.find(id => re.test(id)) || '';
    return {
      boiler: pick(temp, /bojler|boiler|tank/i),
      valve: pick(ids.filter(id => /^(switch|valve)\./.test(id)), /valve|ventil/i),
    };
  }
}

